def choose_move(observation):
    # Defensive defaults
    grid = observation.get("grid", {})
    pos = observation.get("position", observation.get("player", {}))
    x, y = pos.get("x", 0), pos.get("y", 0)

    # Initialize movement to stay still
    dx = 0
    dy = 0

    # Helpers to safely access nearby cells
    def has_gold(nx, ny):
        return grid.get((nx, ny), {}).get("resource") == "gold" or grid.get((nx, ny), {}).get("gold", False)

    def is_enemy(nx, ny):
        cell = grid.get((nx, ny), {})
        return cell.get("owner") and cell.get("owner") != observation.get("owner")

    def can_move(nx, ny):
        # bounds check; if grid has bounds, infer from observation
        minx = observation.get("min_x", -float("inf"))
        maxx = observation.get("max_x", float("inf"))
        miny = observation.get("min_y", -float("inf"))
        maxy = observation.get("max_y", float("inf"))
        if nx < minx or nx > maxx or ny < miny or ny > maxy:
            return False
        # avoid blocking by forcing movement inside
        cell = grid.get((nx, ny), {})
        return not cell.get("blocked", False)

    # Simple defensive heuristic:
    #  - If there is gold adjacent, move toward it.
    #  - If an enemy is adjacent, prefer moving away.
    #  - Otherwise, explore by moving in a consistent small pattern.
    # Scan 4-neighborhood for targets
    targets = []
    for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
        if can_move(nx, ny):
            if has_gold(nx, ny):
                targets.append((nx, ny, 2))  # high priority
            if is_enemy(nx, ny):
                targets.append((nx, ny, -1))  # avoid

    if targets:
        # pick best score: prefer gold, then avoid enemies, then closest
        targets.sort(key=lambda t: ( -t[2], abs(t[0]-x)+abs(t[1]-y) ))
        tx, ty, _ = targets[0]
        dx = 0 if tx == x else (1 if tx > x else -1)
        dy = 0 if ty == y else (1 if ty > y else -1)
        if can_move(x+dx, y+dy):
            return [dx, dy]

    # If no direct target, do a simple deterministic exploration pattern
    # Try to move right, then down, then left, then up (cycle)
    for cand in ((1,0), (0,1), (-1,0), (0,-1)):
        nx, ny = x + cand[0], y + cand[1]
        if can_move(nx, ny):
            return [cand[0], cand[1]]

    # If all else fails, stay put
    return [0, 0]

